#!/usr/bin/env python3
"""Rebuild sitemap.xml and llms.txt from the pages themselves.

sitemap.xml lists exactly the indexable pages of tools/check.py with, for each, the date of the last commit that
touched its file (or today, for a file not yet committed) — a real modification date, never the build date.
llms.txt repeats each page's title and description, so it cannot drift from the HTML. Run from the repo root.
"""
import datetime, html, re, subprocess, sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(ROOT / 'tools'))
from check import PAGES, SITE_URL


def last_change(path):
    out = subprocess.run(['git', 'log', '-1', '--format=%cs', '--', path], cwd=ROOT, capture_output=True, text=True).stdout.strip()
    dirty = subprocess.run(['git', 'status', '--porcelain', '--', path], cwd=ROOT, capture_output=True, text=True).stdout.strip()
    return datetime.date.today().isoformat() if (dirty or not out) else out


def meta(path):
    s = (ROOT / path).read_text(encoding='utf-8')
    title = html.unescape(re.search(r'<title>(.*?)</title>', s, re.S).group(1).strip())
    desc = html.unescape(re.search(r'<meta name="description" content="([^"]*)"', s).group(1))
    return title, desc


urls = []
for route, path in PAGES.items():
    urls.append('  <url>\n    <loc>%s%s</loc>\n    <lastmod>%s</lastmod>\n  </url>' % (SITE_URL, route, last_change(path)))
(ROOT / 'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n'
    '<!-- Exactly the indexable pages, rebuilt by tools/sitemap.py; lastmod is the last commit that touched the page. -->\n'
    '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n%s\n</urlset>\n' % '\n'.join(urls), encoding='utf-8', newline='\n')

lines = ['# Kleo AI', '',
    '> Kleo is an AI creative studio you use by chatting, at https://app.kleooai.com: videos, pictures, voiceovers, music, sound effects, ready-made apps and complete narrated 4K films. For every request Kleo proposes a card with the model, the settings and the exact credit price, and nothing is charged until you tap Generate. The same Kleo also works inside Claude, ChatGPT, Grok, Cursor and Claude Code as a remote MCP server (https://mcp.kleooai.com/mcp), with the same account and credits.',
    '', '## Pages']
for route, path in PAGES.items():
    t, d = meta(path)
    lines.append('- [%s](%s%s): %s' % (t, SITE_URL, route, d))
lines += ['', '## Published product information (checked 14 October 2026)', '',
    'The Kleo app (https://app.kleooai.com): chat with Kleo and attach photos, video clips or sound clips; Kleo proposes a card with the model, settings and exact credit price; credits move only when you tap Generate, and a failed generation is refunded. Video: Seedance 2.5 (default), Seedance 2.0, Seedance 2.0 Fast (cheapest), Google Veo 3.1 and Veo 3.1 Fast (maximum quality), with photo, clip and sound references, 24 camera and effect presets and Prompt Enhance. Pictures: Nano Banana Pro, Nano Banana 2, Seedream 5, FLUX.2 Pro, in sets of 1, 2 or 4. Audio: voiceover, music, sound effects. Apps: Face Swap, Video Face Swap, Talking Photo, Lipsync, Motion Control, Outfit Swap, Edit Video, Upscale Video. Kleo Films (below) can be ordered from the same chat. A library keeps what you make. Sign-in with e-mail, or with the Kleo key of an existing connector account. Example prices: Seedance 2.0 Fast 5 s 480p = 1 credit; Seedance 2.5 5 s 720p = 4; Veo 3.1 Fast 8 s = 3; Veo 3.1 8 s = 7; other prices are shown on the card before generating. Free credits work with Seedance 2.0 Fast and every picture model except Nano Banana Pro; the first pack opens every model.',
    'Film: moving footage generated by Seedance 2.5 from Nano Banana Pro frames, 15 seconds to 5 minutes, realistic or animation look, 16:9 or 9:16, English (default) or Italian narration. Output: 4K 60 fps MP4. Optional AI upscale for a film (Real-ESRGAN + RIFE): the film’s credits again, at least 5, refunded automatically if it cannot be applied. Music track (Suno) and burned-in subtitles on request. Animatic: drawn frames with camera movement and narration, up to 60 seconds, 5 credits up to 20 seconds and 10 up to 60, each picture drawn once. The intake asks in one message: look, film or animatic, AI upscale, music, subtitles, narration language. A vision model checks every picture against the request; your own photos can be the character references.',
    'New accounts receive 5 starter credits, enough for one animatic of up to 20 seconds; confirming an optional email adds 3. Films require a credit-pack purchase and enough eligible credits: max(10, ceil(duration_seconds / 1.5)). Packs: €5 = 10 purchased credits, €15 = 35, €40 = 100; one-off purchases. A 15-second film costs 10 credits; 20 seconds 14; 30 seconds 20; 60 seconds 40. Launch codes PRODUCTHUNT, HN, REDDIT, X and TIKTOK each open one film of up to 15 seconds for an account that has not paid, once per account, for the first 30 accounts per code (tool kleo_redeem, or the account page). Referral: a new account made through a referral link gets 5 extra credits on its first pack and the referrer 10. Confirm usable film credits rather than assuming gifted credits are eligible. Treatment and exact cost are reviewed before rendering.',
    'Download and save files within 7 days; publishing is manual. Current Terms specify a small Kleo mark and require permission before reselling output as your own service. Privacy lists prompts, storyboards and account activity as retained until deletion is requested. Read the full Terms and Privacy for conditions. These are summaries of published policies, not independent production tests.',
    'MCP endpoint: https://mcp.kleooai.com/mcp (Streamable HTTP, OAuth; an optional ?src=<channel> names the launch channel). Custom connector access depends on the assistant, account and workspace. Support: kleooai@gmail.com. Sources: https://kleooai.com/pricing/ https://kleooai.com/faq/ https://kleooai.com/terms.html https://kleooai.com/privacy.html https://kleooai.com/connect/',
    '']
(ROOT / 'llms.txt').write_text('\n'.join(lines), encoding='utf-8', newline='\n')
print('sitemap.xml: %d urls; llms.txt: %d pages' % (len(urls), len(PAGES)))
